265	func TestPackageNeverStartsAProcess(t *testing.T) {
266		entries, err := os.ReadDir(".")
267		if err != nil {
268			t.Fatal(err)
269		}
270		fset := token.NewFileSet()
271		files := 0
272		for _, e := range entries {
273			if e.IsDir() || !strings.HasSuffix(e.Name(), ".go") {
274				continue
275			}
276			src, err := os.ReadFile(e.Name())
277			if err != nil {
278				t.Fatal(err)
279			}
280			files++
281			offences, err := guardSource(fset, e.Name(), src)
282			if err != nil {
283				t.Errorf("%s: %v", e.Name(), err)
284				continue
285			}
286			for _, o := range offences {
287				t.Error(o + ": the trace must not start or exec a process")
288			}
289		}
290		if files == 0 {
291			t.Error("the scan saw no Go file: the guard would pass vacuously")
292		}
293	}
